-- Canonical PostgreSQL commercial expansion. Additive; run after 001 and 002.
BEGIN;
CREATE TABLE IF NOT EXISTS workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NOT NULL REFERENCES organisations(id), name text NOT NULL, slug text NOT NULL, status text NOT NULL DEFAULT 'active', settings jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organisation_id,slug));
CREATE TABLE IF NOT EXISTS memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NOT NULL REFERENCES organisations(id), workspace_id uuid NULL REFERENCES workspaces(id), user_id uuid NOT NULL REFERENCES users(id), role_code text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS memberships_scope_user_uq ON memberships(organisation_id,COALESCE(workspace_id,'00000000-0000-0000-0000-000000000000'::uuid),user_id);
CREATE TABLE IF NOT EXISTS plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, status text NOT NULL DEFAULT 'draft', limits jsonb NOT NULL DEFAULT '{}', features jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS prices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES plans(id), currency char(3) NOT NULL, interval_code text NOT NULL, amount_minor bigint NULL, tax_inclusive boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NOT NULL REFERENCES organisations(id), plan_id uuid NOT NULL REFERENCES plans(id), provider text NOT NULL DEFAULT 'disabled', provider_ref text NULL, status text NOT NULL DEFAULT 'pending', current_period_start timestamptz NULL, current_period_end timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS subscriptions_org_status_idx ON subscriptions(organisation_id,status);
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NOT NULL REFERENCES organisations(id), subscription_id uuid NULL REFERENCES subscriptions(id), invoice_number text UNIQUE NOT NULL, currency char(3) NOT NULL, total_minor bigint NOT NULL DEFAULT 0, tax_minor bigint NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'draft', issued_at timestamptz NULL, due_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NOT NULL REFERENCES organisations(id), invoice_id uuid NULL REFERENCES invoices(id), provider text NOT NULL, provider_ref text NULL, amount_minor bigint NOT NULL, currency char(3) NOT NULL, status text NOT NULL DEFAULT 'pending', idempotency_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NULL REFERENCES organisations(id), slug text NOT NULL, name text NOT NULL, category text NOT NULL, status text NOT NULL DEFAULT 'planned', auth_type text NOT NULL, scope jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS integrations_scope_slug_uq ON integrations(COALESCE(organisation_id,'00000000-0000-0000-0000-000000000000'::uuid),slug);
CREATE TABLE IF NOT EXISTS integration_installations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NOT NULL REFERENCES organisations(id), integration_id uuid NOT NULL REFERENCES integrations(id), status text NOT NULL DEFAULT 'pending', credential_ref text NULL, settings jsonb NOT NULL DEFAULT '{}', last_health_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS marketplace_publishers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid UNIQUE NOT NULL REFERENCES organisations(id), status text NOT NULL DEFAULT 'application', display_name text NOT NULL, reviewed_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS marketplace_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), publisher_id uuid NOT NULL REFERENCES marketplace_publishers(id), slug text UNIQUE NOT NULL, item_type text NOT NULL, name text NOT NULL, status text NOT NULL DEFAULT 'draft', description text NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS marketplace_entitlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NOT NULL REFERENCES organisations(id), item_id uuid NOT NULL REFERENCES marketplace_items(id), status text NOT NULL DEFAULT 'active', starts_at timestamptz NOT NULL DEFAULT now(), ends_at timestamptz NULL, UNIQUE(organisation_id,item_id));
CREATE TABLE IF NOT EXISTS partner_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_name text NOT NULL, email text NOT NULL, partner_type text NOT NULL, status text NOT NULL DEFAULT 'received', details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS academy_courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, level_code text NOT NULL, status text NOT NULL DEFAULT 'draft', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS academy_lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES academy_courses(id), lesson_index integer NOT NULL, title text NOT NULL, content_ref text NULL, status text NOT NULL DEFAULT 'draft', UNIQUE(course_id,lesson_index));
CREATE TABLE IF NOT EXISTS academy_enrolments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NULL REFERENCES organisations(id), user_id uuid NOT NULL REFERENCES users(id), course_id uuid NOT NULL REFERENCES academy_courses(id), status text NOT NULL DEFAULT 'active', enrolled_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz NULL, UNIQUE(user_id,course_id));
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NULL REFERENCES organisations(id), user_id uuid NULL REFERENCES users(id), channel text NOT NULL, template_code text NOT NULL, status text NOT NULL DEFAULT 'queued', payload jsonb NOT NULL, scheduled_at timestamptz NULL, sent_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_queue_idx ON notifications(status,scheduled_at);
CREATE TABLE IF NOT EXISTS sales_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_type text NOT NULL, email text NOT NULL, name text NULL, organisation_name text NULL, status text NOT NULL DEFAULT 'received', consent_at timestamptz NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NULL REFERENCES organisations(id), user_id uuid NULL REFERENCES users(id), email text NULL, priority text NOT NULL DEFAULT 'normal', status text NOT NULL DEFAULT 'open', subject text NOT NULL, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS content_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_type text NOT NULL, slug text NOT NULL, locale text NOT NULL DEFAULT 'en-ZA', status text NOT NULL DEFAULT 'draft', title text NOT NULL, body jsonb NOT NULL DEFAULT '{}', published_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(content_type,slug,locale));
CREATE TABLE IF NOT EXISTS feature_flags (flag_key text PRIMARY KEY, enabled boolean NOT NULL DEFAULT false, scope_type text NOT NULL DEFAULT 'global', scope_id uuid NULL, metadata jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analytics_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NULL REFERENCES organisations(id), workspace_id uuid NULL REFERENCES workspaces(id), event_type text NOT NULL, subject_type text NULL, subject_id uuid NULL, properties jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS analytics_events_org_time_idx ON analytics_events(organisation_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS security_incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), severity text NOT NULL, status text NOT NULL DEFAULT 'open', title text NOT NULL, summary text NULL, opened_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz NULL);

ALTER TABLE workspaces ENABLE ROW LEVEL SECURITY; ALTER TABLE memberships ENABLE ROW LEVEL SECURITY; ALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY; ALTER TABLE invoices ENABLE ROW LEVEL SECURITY; ALTER TABLE payments ENABLE ROW LEVEL SECURITY; ALTER TABLE integration_installations ENABLE ROW LEVEL SECURITY; ALTER TABLE analytics_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY workspaces_org_isolation ON workspaces USING (organisation_id=current_setting('app.organisation_id',true)::uuid);
CREATE POLICY memberships_org_isolation ON memberships USING (organisation_id=current_setting('app.organisation_id',true)::uuid);
CREATE POLICY subscriptions_org_isolation ON subscriptions USING (organisation_id=current_setting('app.organisation_id',true)::uuid);
CREATE POLICY invoices_org_isolation ON invoices USING (organisation_id=current_setting('app.organisation_id',true)::uuid);
CREATE POLICY payments_org_isolation ON payments USING (organisation_id=current_setting('app.organisation_id',true)::uuid);
CREATE POLICY integration_installations_org_isolation ON integration_installations USING (organisation_id=current_setting('app.organisation_id',true)::uuid);
CREATE POLICY analytics_events_org_isolation ON analytics_events USING (organisation_id=current_setting('app.organisation_id',true)::uuid);
COMMIT;
